import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class ListComparison {
    public static void main(String[] args) {
        // ArrayList: acceso rapido por indice
        ArrayList<String> arrayList = new ArrayList<>();
        arrayList.add("A");
        arrayList.add("B");
        arrayList.add("C");
        String element = arrayList.get(1); // O(1)

        // LinkedList: insercion/eliminacion en extremos O(1)
        LinkedList<String> linkedList = new LinkedList<>();
        linkedList.addFirst("X");
        linkedList.addLast("Y");
        linkedList.removeFirst();

        // En la practica, ArrayList es preferible
        // por localidad de referencia en cache
        List<String> preferred = new ArrayList<>();
        for (int i = 0; i < 10000; i++) {
            preferred.add("item" + i);
        }
        // get por indice en ArrayList es mucho mas rapido
    }
}

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.TreeSet;

public class SetComparison {
    public static void main(String[] args) {
        // HashSet: O(1), sin orden
        Set<String> hashSet = new HashSet<>();
        hashSet.add("Banana");
        hashSet.add("Apple");
        hashSet.add("Cherry");
        // Iteracion en orden indefinido
        for (String fruit : hashSet) {
            System.out.println(fruit);
        }

        // LinkedHashSet: O(1), orden de insercion
        Set<String> linkedHashSet = new LinkedHashSet<>();
        linkedHashSet.add("Banana");
        linkedHashSet.add("Apple");
        linkedHashSet.add("Cherry");
        // Iteracion: Banana, Apple, Cherry

        // TreeSet: O(log n), orden natural
        Set<String> treeSet = new TreeSet<>();
        treeSet.add("Banana");
        treeSet.add("Apple");
        treeSet.add("Cherry");
        // Iteracion: Apple, Banana, Cherry
        System.out.println("Primero: " + ((TreeSet<String>) treeSet).first());
    }
}

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;

public class MapComparison {
    public static void main(String[] args) {
        // HashMap: O(1), sin orden
        Map<String, Integer> hashMap = new HashMap<>();
        hashMap.put("apple", 3);
        hashMap.put("banana", 5);
        int count = hashMap.getOrDefault("orange", 0); // O(1)

        // LinkedHashMap: orden de insercion
        Map<String, Integer> linkedMap = new LinkedHashMap<>();
        linkedMap.put("first", 1);
        linkedMap.put("second", 2);
        // Iteracion respeta orden: first, second

        // TreeMap: O(log n), claves ordenadas
        TreeMap<String, Integer> treeMap = new TreeMap<>();
        treeMap.put("cherry", 3);
        treeMap.put("apple", 1);
        treeMap.put("banana", 2);
        String firstKey = treeMap.firstKey(); // "apple"
        String lastKey = treeMap.lastKey(); // "cherry"

        // Navegacion avanzada con NavigableMap
        NavigableMap<String, Integer> nav = treeMap;
        String ceiling = nav.ceilingKey("ban"); // "banana"
        String lower = nav.lowerKey("cherry"); // "banana"
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.Queue;

public class QueueDemo {
    public static void main(String[] args) {
        // Queue FIFO con ArrayDeque
        Queue<String> queue = new ArrayDeque<>();
        queue.offer("first");
        queue.offer("second");
        queue.offer("third");
        String head = queue.poll(); // "first"

        // Deque como pila
        Deque<String> stack = new ArrayDeque<>();
        stack.push("bottom");
        stack.push("top");
        String top = stack.peek(); // "top"

        // Deque como cola
        Deque<String> deque = new ArrayDeque<>();
        deque.offerLast("back");
        deque.offerFirst("front");
        String front = deque.pollFirst(); // "front"

        // PriorityQueue: min-heap
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.add(3);
        pq.add(1);
        pq.add(2);
        int min = pq.poll(); // 1
        int next = pq.poll(); // 2
    }
}

import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

public class EqualsHashCodeContract {
    public static void main(String[] args) {
        Set<Persona> personas = new HashSet<>();
        personas.add(new Persona(1, "Ana"));
        personas.add(new Persona(2, "Luis"));

        // Busca por contenido, no por referencia
        Persona buscada = new Persona(1, "Ana");
        boolean existe = personas.contains(buscada); // true
        System.out.println("Encontrada: " + existe);

        // Sin equals/hashCode correcto, contains retornaria false
        // porque el hashCode calculado seria distinto
        System.out.println("Size: " + personas.size());
    }

    static class Persona {
        int id;
        String nombre;

        Persona(int id, String nombre) {
            this.id = id;
            this.nombre = nombre;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Persona p)) return false;
            return id == p.id && Objects.equals(nombre, p.nombre);
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, nombre);
        }
    }
}

import java.util.Objects;

public class SafeEqualsHashCode {
    private final int id;
    private final String nombre;
    private final double salario;

    public SafeEqualsHashCode(int id, String nombre, double salario) {
        this.id = id;
        this.nombre = nombre;
        this.salario = salario;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SafeEqualsHashCode that)) return false;
        return id == that.id
            && Double.hashCode(salario) == Double.hashCode(that.salario)
            && Objects.equals(nombre, that.nombre);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, nombre, Double.hashCode(salario));
    }

    // Con record, todo esto es automatico:
    // public record Persona(int id, String nombre, double salario) {}
}

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class MutableKeyProblem {
    public static void main(String[] args) {
        Map<MiClave, String> map = new HashMap<>();

        MiClave clave = new MiClave(1, "original");
        map.put(clave, "valor1");
        System.out.println(map.get(clave)); // "valor1"

        // Modificar la clave cambia su hashCode
        clave.nombre = "modificado";

        // La clave se busca en el bucket incorrecto
        System.out.println(map.get(clave)); // null
        System.out.println(map.size()); // 1 pero inaccesible

        // Solucion: usar claves inmutables
        record ClaveInmutable(int id, String nombre) {}
        Map<ClaveInmutable, String> safe = new HashMap<>();
        safe.put(new ClaveInmutable(1, "ana"), "ok");
    }

    static class MiClave {
        int id;
        String nombre;

        MiClave(int id, String nombre) {
            this.id = id;
            this.nombre = nombre;
        }

        @Override
        public int hashCode() {
            return Objects.hash(id, nombre);
        }
    }
}

import java.util.Comparator;
import java.util.TreeMap;
import java.util.TreeSet;

public class ComparableVsComparator {
    public static void main(String[] args) {
        // Comparable: orden natural dentro de la clase
        record Producto(String nombre, double precio)
            implements Comparable<Producto> {

            @Override
            public int compareTo(Producto other) {
                return Double.compare(this.precio, other.precio);
            }
        }

        TreeSet<Producto> porPrecio = new TreeSet<>();
        porPrecio.add(new Producto("Laptop", 999.99));
        porPrecio.add(new Producto("Mouse", 25.50));
        // Itera ordenado por precio

        // Comparator: criterio alternativo externo
        Comparator<Producto> porNombre =
            Comparator.comparing(Producto::nombre);

        TreeSet<Producto> porNombreSet = new TreeSet<>(porNombre);
        porNombreSet.add(new Producto("Laptop", 999.99));
        porNombreSet.add(new Producto("Mouse", 25.50));
        // Itera ordenado por nombre

        // TreeMap con Comparator personalizado
        TreeMap<String, Integer> longitudClave = new TreeMap<>(
            Comparator.comparingInt(String::length)
        );
        longitudClave.put("uno", 1);
        longitudClave.put("diez", 10);
    }
}

