import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ViewVsCopy {
    public static void main(String[] args) {
        List<String> original = new ArrayList<>(
            List.of("a", "b", "c")
        );

        // Vista inmutable: refleja cambios de la original
        List<String> vista = Collections.unmodifiableList(original);
        original.add("d");
        System.out.println(vista); // [a, b, c, d]
        // vista.add("x") lanza UnsupportedOperationException

        // Copia inmutable: independiente de la original
        List<String> copia = List.copyOf(original);
        original.add("e");
        System.out.println(copia); // [a, b, c, d]
        System.out.println(original); // [a, b, c, d, e]
        // copia.add("y") lanza UnsupportedOperationException

        // Para colecciones vacias: reutiliza instancia
        List<String> vacia1 = Collections.emptyList();
        List<String> vacia2 = Collections.emptyList();
        System.out.println(vacia1 == vacia2); // true
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ImmutabilityConcurrency {
    private final Map<String, List<String>> cache = new HashMap<>();

    public void addItem(String key, String item) {
        cache.computeIfAbsent(key, k -> new ArrayList<>()).add(item);
    }

    // Devolver copia inmutable para proteger el estado interno
    public List<String> getItems(String key) {
        List<String> items = cache.getOrDefault(key, List.of());
        return List.copyOf(items); // copia defensiva
    }

    // Vista inmutable (peor: refleja cambios internos)
    public List<String> getItemsUnsafe(String key) {
        return Collections.unmodifiableList(
            cache.getOrDefault(key, List.of())
        );
    }

    public static void main(String[] args) {
        ImmutabilityConcurrency demo =
            new ImmutabilityConcurrency();
        demo.addItem("frutas", "manzana");
        demo.addItem("frutas", "naranja");

        List<String> frutas = demo.getItems("frutas");
        System.out.println(frutas); // [manzana, naranja]
        // frutas.add("uva") lanza UnsupportedOperationException
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

public class StreamImmutability {
    public static void main(String[] args) {
        List<String> mutable = new ArrayList<>(
            List.of("a", "b", "c", "a", "b")
        );

        // toList() produce lista inmutable desde Java 16
        List<String> immutable = Stream.of("x", "y", "z")
            .toList();
        // immutable.add("w") lanza UnsupportedOperationException

        // distinct() elimina duplicados con equals/hashCode
        List<String> unicos = mutable.stream()
            .distinct()
            .toList();
        System.out.println(unicos); // [a, b, c]

        // toList() es preferible a collect(Collectors.toList())
        // porque produce una lista inmutable (mas seguro)
        List<Integer> cuadrados = Stream.iterate(1, n -> n + 1)
            .limit(5)
            .map(n -> n * n)
            .toList();
        System.out.println(cuadrados); // [1, 4, 9, 16, 25]
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class ComplexityDemo {
    public static void main(String[] args) {
        // ArrayList: O(1) get, O(n) insert/remove
        List<String> list = new ArrayList<>();
        list.add("a");
        list.add("b");
        list.add("c");
        String get = list.get(1); // O(1)
        list.add(1, "x"); // O(n) desplaza elementos

        // HashMap: O(1) promedio
        Map<String, Integer> map = new HashMap<>();
        map.put("key", 1); // O(1)
        map.get("key"); // O(1)
        map.containsKey("key"); // O(1)

        // TreeMap: O(log n) con orden
        TreeMap<String, Integer> tree = new TreeMap<>();
        tree.put("banana", 2); // O(log n)
        tree.put("apple", 1);
        tree.get("apple"); // O(log n)

        // Navegacion ordenada en TreeMap
        tree.firstKey(); // O(1)
        tree.lastKey(); // O(1)
        tree.lowerKey("banana"); // O(log n)
        tree.higherKey("banana"); // O(log n)
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class SafeRemoval {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(
            List.of("apple", "banana", "cherry", "date")
        );

        // Forma 1: iterator.remove()
        Iterator<String> it = list.iterator();
        while (it.hasNext()) {
            String item = it.next();
            if (item.length() < 6) {
                it.remove(); // seguro
            }
        }
        System.out.println(list); // [cherry]

        // Forma 2: removeIf (preferido, mas limpio)
        List<Integer> numeros = new ArrayList<>(
            List.of(1, 2, 3, 4, 5, 6, 7, 8)
        );
        numeros.removeIf(n -> n % 2 == 0); // elimina pares
        System.out.println(numeros); // [1, 3, 5, 7]

        // ERROR: ConcurrentModificationException
        // for (String s : list) {
        //     if (s.length() < 6) list.remove(s);
        // }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class MapFunctionalMethods {
    public static void main(String[] args) {
        Map<String, List<String>> groups = new HashMap<>();

        // computeIfAbsent: crea la lista solo si no existe
        String name = "employees";
        groups.computeIfAbsent(name, k -> new ArrayList<>())
              .add("Alice");
        groups.computeIfAbsent(name, k -> new ArrayList<>())
              .add("Bob");
        System.out.println(groups.get("employees"));

        // merge: combina valores existentes con nuevos
        Map<String, Integer> wordCount = new HashMap<>();
        String[] words = {"java", "code", "java", "java"};
        for (String word : words) {
            wordCount.merge(word, 1, Integer::sum);
        }
        System.out.println(wordCount); // {java=3, code=1}

        // forEach: itera sobre cada entrada
        wordCount.forEach((word, count) ->
            System.out.println(word + ": " + count)
        );

        // putIfAbsent: inserta solo si la clave no existe
        Map<String, Integer> scores = new HashMap<>();
        scores.putIfAbsent("math", 95);
        scores.putIfAbsent("math", 100); // no sobreescribe
        System.out.println(scores.get("math")); // 95
    }
}

import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class ConcurrentCollections {
    public static void main(String[] args) {
        // ConcurrentHashMap: locks granulares
        ConcurrentHashMap<String, Integer> cmap =
            new ConcurrentHashMap<>();
        cmap.put("key", 1);
        cmap.putIfAbsent("key", 2); // no sobreescribe
        cmap.merge("key", 1, Integer::sum); // atomico
        Integer val = cmap.get("key"); // sin lock

        // Operaciones atomicas
        cmap.compute("key", (k, v) -> v == null ? 1 : v + 1);
        cmap.computeIfAbsent("new", k -> 42);

        // Collections.synchronizedMap: un solo lock
        Map<String, Integer> syncMap =
            Collections.synchronizedMap(new ConcurrentHashMap<>());

        // CopyOnWriteArrayList: ideal para lecturas frecuentes
        CopyOnWriteArrayList<String> cow =
            new CopyOnWriteArrayList<>();
        cow.add("read-only"); // crea copia interna
        // Iteracion no lanza ConcurrentModificationException
        for (String s : cow) {
            System.out.println(s);
        }
    }
}
